import { test, expect } from '../../fixtures';
import { Page } from '@playwright/test';
import * as fs from 'fs';
import * as path from 'path';
import { runStamp } from '../support/api';
import { createCandidateLink, launchCandidate, goToPractice, tap, timerSeconds, ONE_TIME, blockCallStarts } from './support';
import { fakePeer, mockCallBackend, expectLive, LIVE_STATUS } from '../call-quality/support';
import { MIC, END, START_BUTTONS, NO_RESULTS, syntheticMic, setMic, micStats, mockEnd, expectMicLossShown } from './mic-loss-support';

const HASH = '#17fdd9';

/** business → кандидат → Chrome кандидата с подменами и синтетическим микрофоном → экран «פרטי לקוח לשיחה». */
async function prepare(asUser: (id: string) => Promise<Page>, tag: string, endStatus: 'completed' | 'technical_failure', micLevel = 0.3) {
  const business = await asUser('business');
  const name = `QA-AUTO-17FDD9-${tag}-${runStamp()}`;
  const link = await createCandidateLink(business, name);
  test.info().annotations.push({ type: 'test-data', description: `кандидат «${name}» (официальная попытка НЕ использована — старт подменён), не удаляется` });
  const cand = await launchCandidate({ width: 390, height: 844 });
  await syntheticMic(cand.ctx, micLevel);
  await fakePeer(cand.ctx, { rttMs: 150, jbMs: 40, lossPct: 0 });
  const page = cand.page;
  const mocked = await mockCallBackend(page, 300);
  const ended = await mockEnd(page, endStatus);
  await goToPractice(page, link);
  await tap(page, 'לדלג ישר לשיחה הרשמית');
  return { cand, page, mocked, ended, name };
}

/** Экран подтверждения → галочка → «מוכן, מתחילים» → живой звонок. */
async function startOfficial(page: Page, mocked: { start: number; voice: number }) {
  await page.getByRole('checkbox', { name: ONE_TIME.confirm }).check();
  await tap(page, 'מוכן, מתחילים');
  await expectLive(page);
  expect(mocked.start, 'candidate_start_attempt (подменённый)').toBe(1);
  expect(mocked.voice, 'start-voice-session (подменённый)').toBe(1);
}

test.describe(`Официальный звонок: одноразовость, звонок без подсказок, конец, потеря микрофона (${HASH})`, () => {
  test(`AC1/AC2/AC4: плашка «חד-פעמי» + галочка (без неё старта нет) → живой экран с таймером и статусом, без подсказок и оценок → «לסיים שיחה» → «הסימולציה הושלמה» без результатов @desktop @data ${HASH}`, async ({ asUser }) => {
    test.setTimeout(4 * 60_000);
    const { cand, page, mocked, ended } = await prepare(asUser, 'AC', 'completed');
    try {
      // Источник: AC1 / דרישה 1 — перед официальной попыткой сообщение «одноразовая, кроме сбоя/исключения» и явное подтверждение.
      await expect(page.getByText(ONE_TIME.officialWarn)).toBeVisible();
      await expect(page.getByText(ONE_TIME.officialRetryRule)).toBeVisible();
      const box = page.getByRole('checkbox', { name: ONE_TIME.confirm });
      await expect(box).not.toBeChecked();
      await tap(page, 'מוכן, מתחילים');
      await expect(page.getByText(ONE_TIME.confirmRequired)).toBeVisible();
      expect(mocked.start + mocked.voice, 'старт без галочки').toBe(0);

      await box.check();
      await tap(page, 'מוכן, מתחילים');
      await expectLive(page);
      expect(mocked.start, 'candidate_start_attempt (подменённый)').toBe(1);

      // Источник: AC2 / דרישה 2 — в ходе звонка таймер и статус соединения, без подсказок, оценок и фидбэка.
      const t0 = await timerSeconds(page);
      await expect.poll(() => timerSeconds(page), { message: 'таймер звонка не идёт', timeout: 15_000 }).toBeLessThan(t0);
      await expect(page.getByRole('status').filter({ hasText: LIVE_STATUS })).toBeVisible();
      expect(await page.locator('body').innerText(), 'подсказки/оценки во время звонка').not.toMatch(NO_RESULTS);

      // Источник: AC4 / דרישה 5 — завершение: экран «הסימולציה הושלמה», без результатов; повторить нельзя.
      await tap(page, 'לסיים שיחה');
      await tap(page, 'לאשר סיום שיחה');
      await expect(page.getByText(END.doneTitle, { exact: true })).toBeVisible({ timeout: 30_000 });
      expect(ended, 'end-candidate-attempt вызван один раз').toHaveLength(1);
      expect(await page.locator('body').innerText(), 'результаты/оценка на экране завершения').not.toMatch(NO_RESULTS);
      await expect(page.getByRole('button', { name: START_BUTTONS })).toHaveCount(0);
      expect(mocked.openai, 'запросы к OpenAI').toBe(0);
    } finally {
      await cand.browser.close();
    }
  });

  test(`FL-29 ш.1/ш.2: цифровой ноль 3 с → за ≤5,5 с статус «המיקרופון לא זמין · מנסים להחזיר אותו» и карточка «אין גישה למיקרופון — השיחה ממשיכה…», звонок идёт; звук вернулся → ≤4 с «מחובר · הלקוח מקשיב», карточка исчезла @desktop @data ${HASH}`, async ({ asUser }) => {
    test.setTimeout(4 * 60_000);
    const { cand, page, mocked, ended } = await prepare(asUser, 'MIC', 'technical_failure');
    try {
      await startOfficial(page, mocked);
      await expect(page.getByText(MIC.cardTitle, { exact: true })).toHaveCount(0);
      const reqBefore = (await micStats(page)).requests;

      // Источник: комментарий программиста 17.11 / реджект 3 — потеря = 3 с подряд точный ноль; подсказка за ~3,5 с.
      await setMic(page, 0);
      const t0 = Date.now();
      await expectMicLossShown(page, 5_500);
      test.info().annotations.push({ type: 'mic-loss-prompt-ms', description: String(Date.now() - t0) });
      // На десктопном UA шаг про «הגדרות המהירות של Android» не показывается (только на Android UA).
      await expect(page.getByText(MIC.androidStep)).toHaveCount(0);
      await expect(page.getByText('לחצו על סמל המנעול או ההגדרות משמאל לכתובת האתר.')).toBeVisible();
      // «השיחה ממשיכה»: фаза live, таймер идёт, конец попытки не вызывался.
      await expect(page.getByTestId('call-stage')).toHaveAttribute('data-phase', 'live');
      const t1 = await timerSeconds(page);
      await expect.poll(() => timerSeconds(page), { timeout: 10_000 }).toBeLessThan(t1);
      expect(ended, 'попытка не должна завершаться сразу').toHaveLength(0);
      // Источник: FL-29 ш.1 — «…ומנסה לחדש חיבור לפני סימון כתקול»: повторный запрос микрофона.
      await expect.poll(async () => (await micStats(page)).requests, { message: 'нет повторного запроса микрофона', timeout: 10_000 }).toBeGreaterThan(reqBefore);

      // Источник: реджект 3, шаг 5 — звук вернулся: статус «מחובר…» и карточка исчезла, звонок продолжается.
      await setMic(page, 0.3);
      await expect(page.getByRole('status').filter({ hasText: LIVE_STATUS })).toBeVisible({ timeout: 4_000 });
      await expect(page.getByText(MIC.cardTitle, { exact: true })).toHaveCount(0, { timeout: 4_000 });
      await expect(page.getByRole('status').filter({ hasText: MIC.status })).toHaveCount(0);
      await expectLive(page);
      expect(ended, 'после восстановления попытка не завершается').toHaveLength(0);
      expect((await micStats(page)).cardShown, 'карточка показывалась ровно один раз').toBe(1);
      expect(mocked.openai, 'запросы к OpenAI').toBe(0);
    } finally {
      await cand.browser.close();
    }
  });

  test(`нет ложного срабатывания: «тихая комната» (пик 2e-4, не ноль) 10 с — ни статуса, ни карточки @desktop @data ${HASH}`, async ({ asUser }) => {
    test.setTimeout(4 * 60_000);
    const { cand, page, mocked } = await prepare(asUser, 'QUIET', 'completed', 0.0002);
    try {
      await startOfficial(page, mocked);
      // Источник: комментарий программиста — тихая комната (пик 2e-4) не триггерит; Т4 брифа. Ожидание по таймеру звонка, без пауз.
      const t0 = await timerSeconds(page);
      await expect.poll(() => timerSeconds(page), { message: 'таймер не прошёл 10 с', timeout: 40_000, intervals: [1_000] }).toBeLessThanOrEqual(t0 - 10);
      expect((await micStats(page)).cardShown, 'карточка «אין גישה למיקרופון» при тихой комнате').toBe(0);
      await expect(page.getByRole('status').filter({ hasText: MIC.status })).toHaveCount(0);
      await expectLive(page);
    } finally {
      await cand.browser.close();
    }
  });

  test(`Т3/AC5/FL-38: ноль дольше 30 с после подсказки (~33 с) → «השיחה לא הושלמה», «השיחה נקטעה בגלל תקלה טכנית», «פנייה לגורם אנושי», без результатов, старта нет; end-candidate-attempt с technical_failure @desktop @data ${HASH}`, async ({ asUser }) => {
    test.setTimeout(4 * 60_000);
    const { cand, page, mocked, ended } = await prepare(asUser, 'FAIL', 'technical_failure');
    try {
      await startOfficial(page, mocked);
      await setMic(page, 0);
      const t0 = Date.now();
      await expectMicLossShown(page, 5_500);
      expect(ended, 'сбой не раньше 30 с после подсказки').toHaveLength(0);

      // Источник: реджект 3 / AC5 / דרישה 6 — «через 30 с — technical failure», экран «что случилось и к кому обратиться».
      await expect(page.getByText(END.failTitle, { exact: true })).toBeVisible({ timeout: 50_000 });
      const sec = (Date.now() - t0) / 1000;
      test.info().annotations.push({ type: 'mic-loss-to-failure-s', description: sec.toFixed(1) });
      expect(sec, 'сбой слишком рано (до 30 с)').toBeGreaterThanOrEqual(25);
      await expect(page.getByText(END.failReason, { exact: true })).toBeVisible();
      await expect(page.getByText(END.failNotYou)).toBeVisible();
      await expect(page.getByText(END.failSaved, { exact: true })).toBeVisible();
      await expect(page.getByRole('button', { name: END.human }).last()).toBeVisible();
      await expect(page.getByText(END.doneTitle, { exact: true })).toHaveCount(0);
      expect(await page.locator('body').innerText(), 'отчёт/оценка кандидату при сбое').not.toMatch(NO_RESULTS);
      await expect(page.getByRole('button', { name: START_BUTTONS })).toHaveCount(0);
      // Источник: AC5 / FL-38 ш.1 — попытка закрыта как технический сбой (не completed), автоматически новая не навязывается.
      expect(ended, 'end-candidate-attempt вызван один раз').toHaveLength(1);
      expect(ended[0].body, 'причина конца попытки').toContain('technical_failure');
      expect(mocked.start, 'новая попытка не стартовала').toBe(1);
      expect(mocked.openai, 'запросы к OpenAI').toBe(0);
    } finally {
      await cand.browser.close();
    }
  });
});

// ---------- Только чтение: готовая ссылка после технического сбоя (QA-PH-1711-2, сбой 17.11 на Pixel 6) ----------
const CAND_FILE = path.resolve(__dirname, '../../../tmp/17fdd9-1711/cand.json');
function failedLink(): string {
  if (process.env.QA_17FDD9_FAILED_LINK) return process.env.QA_17FDD9_FAILED_LINK;
  try {
    const rows = JSON.parse(fs.readFileSync(CAND_FILE, 'utf8')) as { name: string; link: string }[];
    return rows.find((r) => r.name === 'QA-PH-1711-2')?.link || '';
  } catch {
    return '';
  }
}

test.describe(`Ссылка после технического сбоя — только чтение (${HASH})`, () => {
  test(`повторное открытие ссылки QA-PH-1711-2 (сбой микрофона): «השיחה לא הושלמה», «פנייה לגורם אנושי», кнопки старта нет (и после reload), попытка не стартует; без оценки в ответе сервера @mobile @prod-safe ${HASH}`, async ({ asUser }) => {
    const link = failedLink();
    expect(link, 'нет данных: ссылка QA-PH-1711-2 (.qa/tmp/17fdd9-1711/cand.json) или QA_17FDD9_FAILED_LINK').toBeTruthy();
    const guest = await asUser('guest');
    const blocked = await blockCallStarts(guest);
    const opened = guest.waitForResponse((r) => r.url().includes('/rpc/candidate_open_link') && r.request().method() === 'POST');
    await guest.goto(link);
    const body = await (await opened).text();

    // Источник: AC5 / דרישה 3 — автоматически новая попытка не навязывается; AC3 экрана сбоя — путь к человеку (FL-38).
    // Если админ сбросил попытку (איפוס) — ссылка снова активна и тест падает как ОКРУЖЕНИЕ («нет данных»), не как баг.
    await expect(guest.getByText(END.failTitle, { exact: true }), 'нет данных: попытка QA-PH-1711-2 сброшена/ссылка изменена').toBeVisible({ timeout: 30_000 });
    await expect(guest.getByText(END.failReason, { exact: true })).toBeVisible();
    await expect(guest.getByText(END.failNotYou)).toBeVisible();
    await expect(guest.getByRole('button', { name: END.human }).last()).toBeVisible();
    await expect(guest.getByRole('button', { name: START_BUTTONS })).toHaveCount(0);
    expect(await guest.locator('body').innerText()).not.toMatch(NO_RESULTS);
    expect(body, 'candidate_open_link отдаёт оценку/отчёт').not.toMatch(/"(score|overall_score|domains|feedback|checkpoints)"/);

    await guest.reload();
    await expect(guest.getByText(END.failTitle, { exact: true })).toBeVisible({ timeout: 30_000 });
    await expect(guest.getByRole('button', { name: START_BUTTONS })).toHaveCount(0);
    expect(blocked.start + blocked.voice, 'запрос старта попытки/голосовой сессии').toBe(0);
  });
});
